def execute(arguments):
    """
    创建可下载文件

    参数:
        arguments (dict): 包含以下字段
            - filename (str): 文件名
            - content (str): 文件内容（文本或base64编码的二进制）
            - file_path (str): 已有文件路径，如果提供则直接注册该文件
            - description (str): 文件描述
            - encoding (str): 文件编码，默认utf-8，二进制文件用base64

    返回:
        dict: 包含创建结果的字典
    """
    import os
    import uuid
    import base64

    filename = arguments.get("filename", "")
    content = arguments.get("content", "")
    file_path = arguments.get("file_path", "")
    description = arguments.get("description", "")
    encoding = arguments.get("encoding", "utf-8")

    if file_path:
        if not os.path.exists(file_path):
            return {"success": False, "error": f"文件不存在: {file_path}"}

        if not filename:
            filename = os.path.basename(file_path)

        file_size = os.path.getsize(file_path)
        file_uuid = str(uuid.uuid4())

        return {
            "success": True,
            "filename": filename,
            "stored_filename": os.path.basename(file_path),
            "file_path": file_path,
            "size": file_size,
            "download_uuid": file_uuid,
            "description": description,
            "_register_file": True
        }

    if not filename:
        return {"success": False, "error": "请提供文件名"}

    if not content:
        return {"success": False, "error": "请提供文件内容或文件路径"}

    try:
        download_dir = os.path.join(os.getcwd(), "downloads")
        if not os.path.exists(download_dir):
            os.makedirs(download_dir, exist_ok=True)

        file_uuid = str(uuid.uuid4())
        safe_filename = filename.replace("..", "").replace("/", "_").replace("\\", "_")
        stored_filename = f"{file_uuid[:8]}_{safe_filename}"
        file_path = os.path.join(download_dir, stored_filename)

        if encoding.lower() == "base64":
            try:
                binary_content = base64.b64decode(content)
                with open(file_path, "wb") as f:
                    f.write(binary_content)
            except Exception as e:
                return {"success": False, "error": f"base64解码失败: {str(e)}"}
        else:
            with open(file_path, "w", encoding=encoding) as f:
                f.write(content)

        file_size = os.path.getsize(file_path)

        return {
            "success": True,
            "filename": filename,
            "stored_filename": stored_filename,
            "file_path": file_path,
            "size": file_size,
            "download_uuid": file_uuid,
            "description": description,
            "_register_file": True
        }
    except Exception as e:
        return {"success": False, "error": f"创建文件失败: {str(e)}"}
